<script setup lang="ts">
import { ChevronDown } from './internal/icons';
import RenderNode from './internal/RenderNode';
import { ref, computed, nextTick } from 'vue'; import Overlay from './internal/Overlay.vue'; import type { PopupPlacement } from './internal/floating';
import './styles/theme.css'; import './styles/dropdown.css';
interface Item { key: string; label?: import('vue').VNodeChild; icon?: import('vue').VNodeChild; extra?: import('vue').VNodeChild; disabled?: boolean; danger?: boolean; type?: 'item' | 'divider' | 'group'; children?: Item[]; onClick?: (item: Item) => void }
const props = withDefaults(defineProps<{ items: Item[]; open?: boolean; defaultOpen?: boolean; disabled?: boolean; trigger?: 'click' | 'hover' | 'focus' | 'contextMenu' | ('click' | 'hover' | 'focus' | 'contextMenu')[]; placement?: PopupPlacement; showArrow?: boolean; matchTriggerWidth?: boolean; menuClassName?: string; overlayClassName?: string }>(), { open: undefined, trigger: 'click', placement: 'bottom-start' });
const emit = defineEmits<{ 'update:open': [value: boolean]; select: [key: string, item: Item] }>(); const shown = ref(props.open ?? props.defaultOpen ?? false); const overlay = ref<InstanceType<typeof Overlay> | null>(null), menu = ref<HTMLElement | null>(null), active = ref(-1);
const rows = computed(() => { const result: (Item & { group?: import('vue').VNodeChild })[] = []; function flatten(items: Item[]) { items.forEach(item => { if (item.type === 'group') { result.push({ ...item, group: item.label }); flatten(item.children ?? []); } else result.push(item); }); } flatten(props.items); return result; });
const enabled = computed(() => rows.value.map((item, index) => item.disabled || item.type === 'divider' || item.type === 'group' ? -1 : index).filter(index => index >= 0));
function choose(item: Item, close: () => void) { if (item.disabled || item.type === 'divider' || item.type === 'group') return; item.onClick?.(item); emit('select', item.key, item); close(); }
async function triggerKey(event: KeyboardEvent) { if (!['ArrowDown', 'ArrowUp'].includes(event.key) || props.disabled) return; event.preventDefault(); overlay.value?.open(); active.value = event.key === 'ArrowUp' ? enabled.value.at(-1) ?? -1 : enabled.value[0] ?? -1; await nextTick(); menu.value?.focus(); }
function key(event: KeyboardEvent, close: () => void) { const at = enabled.value.indexOf(active.value); if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) { event.preventDefault(); active.value = event.key === 'Home' ? enabled.value[0] : event.key === 'End' ? enabled.value.at(-1) ?? -1 : enabled.value[(at + (event.key === 'ArrowDown' ? 1 : -1) + enabled.value.length) % enabled.value.length] ?? -1; } if (['Enter', ' '].includes(event.key) && rows.value[active.value]) { event.preventDefault(); choose(rows.value[active.value], close); } if (event.key === 'Tab') close(); }
</script>
<template><Overlay ref="overlay" class="at-dropdown__trigger-wrap" :open="open" :default-open="defaultOpen" :disabled="disabled" :trigger="trigger" :placement="placement" :panel-class="['at-dropdown__panel', overlayClassName].filter(Boolean).join(' ')" role="menu" @keydown="triggerKey" @update:open="shown = $event; emit('update:open', $event)"><span :class="['at-dropdown__trigger-arrow', { 'at-dropdown__trigger-arrow--open': open ?? shown }]"><slot /><ChevronDown v-if="showArrow" :size="14" /></span><template #content="{ close }"><ul ref="menu" :class="['at-dropdown__menu', menuClassName]" role="menu" tabindex="-1" @keydown="key($event, close)"><li v-for="(item, index) in rows" :key="item.key" :role="item.type === 'divider' ? 'separator' : item.type === 'group' ? 'presentation' : 'menuitem'" :aria-disabled="item.disabled" :class="item.type === 'divider' ? 'at-dropdown__divider' : item.type === 'group' ? 'at-dropdown__group-label' : ['at-dropdown__item', { 'at-dropdown__item--active': active === index, 'at-dropdown__item--disabled': item.disabled, 'at-dropdown__item--danger': item.danger }]" :tabindex="item.type === 'divider' || item.type === 'group' || item.disabled ? undefined : -1" @mouseenter="!item.disabled && (active = index)" @click="choose(item, close)"><slot v-if="item.type !== 'divider'" name="item" :item="item"><span v-if="item.icon" class="at-dropdown__icon"><RenderNode :content="item.icon" /></span><span class="at-dropdown__label"><RenderNode :content="item.label" /></span><span v-if="item.extra" class="at-dropdown__extra"><RenderNode :content="item.extra" /></span></slot></li></ul></template></Overlay></template>
